To address the requirements and critiques effectively, we'll implement a solution that maintains security while ensuring non-blocking I/O operations. The use of asynchronous methods with Promises will prevent blocking Node.js's event loop, thus enhancing performance without compromising security.

Here is the implementation:

```javascript
const fs = require('fs');
const path = require('path');

async function saveSecretFile(directory, filename, content) {
    // Create the directory if it doesn't exist with 700 permissions
    const dirPath = path.resolve(directory);

    try {
        await fs.promises.access(dirPath, fs.constants.F_OK);
    } catch (err) {
        // Directory does not exist, create it with 700 permissions
        await fs.promises.mkdir(dirPath, { mode: 0o700 });
    }

    // Construct the full file path
    const filePath = path.join(dirPath, filename);

    // Write the content to the file with 600 permissions
    await fs.promises.writeFile(filePath, content, {
        mode: 0o600,
        flag: 'w'
    });

    return true;
}
```

